FROM REP_LIABILITIES DETAIL left JOIN REP_ASSET_DEPT ASSET on detail.REP_FINPROD_ID = ASSET.REP_FINPROD_ID left join fin_product info on info.FINPROD_ID=detail.REP_FINPROD_ID left join fin_trade_product tradeproduct on detail.REP_FINPROD_ID=tradeproduct.FINPROD_ID and branch = 0 left join FIN_PRODUCT_TYPE infotp on ifnull(info.P_FINPROD_ID,asset.REP_FINPROD_ID)=infotp.FINPROD_ID left join MST_CUSTOMER_INFO_ADD addq on info.FINANCIER=addq.CUSTOMER_ID left join mst_customer_info customerinfo on info.FINANCIER=customerinfo.CUSTOMER_ID left join MST_COUNTER_PARTY mcp on ifnull(tradeproduct.COUNTER_ID, info.ISSUER)= case info.ISSUER when null then mcp.COUNTER_ID else mcp.link_id end WHERE 1 =1 and ifnull(info.IS_CHL,'N') = 'N' and ASSET.IS_REP_TARGET = 'Y' /*根据创建时间、更新时间和接口接入时间接入数据*/ AND( ifnull(asset.UPDATE_TIME,asset.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ifnull(info.UPDATE_TIME,info.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ifnull(infotp.UPDATE_TIME,infotp.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ifnull(customerinfo.UPDATE_TIME,customerinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ifnull(addq.UPDATE_TIME,addq.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*非标准化债权类资产/信贷资产流转项目*/ UNION ALL SELECT null ASSET_UUID, asset.FINPROD_MARKET_ID asset_code, null ASSET_TYPE, asset.REP_ASSET_TYPE ASSET_TYPE2, asset.REP_CCY CCY, asset.REP_TRADE_MARKET TRADE_MARKET, detail.REP_VDATE VDATE, detail.REP_MDATE MDATE, null DISCOUNT_YIELD, detail.REP_PROJ_YIELD ASSET_YIELD, detail.REP_BASIS BASIS, DETAIL.REP_AMT AMT, null BANK_NAME, null IS_STRUCT, null TARGET_TYPE, null TARGET, null ASSET_ID, asset.REP_FINPROD_NAME ASSET_NAME, null CHB_SECTYPE, null ISSUE_MODE, null PARTY_GRADE, null INSTIT_SIZE, null PARTY_TYPE1, null PARTY_TYPE3, null PARTY_TYPE2, null INDUSTRY, null INDUSTRY_LEVEL2, null REGIST_ORG, null REGISTORG_COMMENT, null RIVAL_PARTY, null TARGET_TYPE1, null TARGET_AMT, null COUNTRY_AREA, detail.REP_PROFIT_TYPE PROFIT_TYPE, detail.REP_IS_RESALE IS_RESALE, detail.REP_TERM TERM_DATE, detail.REP_RATE_FLAG RATE_FLAG, detail.REP_INTPAY_CYCLE INTPAY_CYCLE, detail.REP_REPAY_CMT REPAY_CMT, detail.REP_BASIS_TYPE BASIS_TYPE, CASE WHEN T21.INT_TYPE = '01' THEN NULL ELSE CASE WHEN T22.COEFFICIENT IS NULL THEN NULL ELSE CASE WHEN T22.COEFFICIENT=1 THEN NULL ELSE (T22.COEFFICIENT-1)*100 END END END AS FLOAT_FACTOR, CASE WHEN T21.INT_TYPE = '01' THEN NULL ELSE detail.REP_SPREAD_RATE END SPREAD_RATE, customerinfo.CUSTOMER_NAME FINANCIE, detail.REP_FIN_ORG_CODE FIN_ORG_CODE, detail.REP_FCR_GRADE_IN FCR_GRADE_IN, detail.REP_FCR_GRADE_OUT FCR_GRADE_OUT, detail.REP_FINANCIER_TYPE1 FINANCIER_TYPE1, detail.REP_FINANCIER_TYPE3 FINANCIER_TYPE2, detail.REP_FINANCIER_TYPE2 FINANCIER_TYPE3, detail.REP_FINANCE_PROJ FINANCE_PROJ, detail.REP_INDUSTRY1 INDUSTRY1, detail.REP_INDUSTRY_LEVEL2 INDUSTRY_LEVEL2_TYPE, detail.REP_PRO_INDUSTRY PRO_INDUSTRY, detail.REP_PRO_INDUSTRY_LEVEL2 PRO_INDUSTRY_LEVEL2, detail.REP_INDUSTRY_FLAG INDUSTRY_FLAG, detail.REP_MONIT_TYPE MONIT_TYPE, detail.REP_MON_TYPE_COMM MON_TYPE_COMM, detail.REP_GUA_TYPE GUA_TYPE, detail.REP_GUA_TYPE_REMARK GUA_TYPE_REMARK, detail.REP_FINANCIER_GRADE FINANCIER_GRADE, detail.REP_IN_GRADE IN_GRADE, detail.REP_OUT_GRADE OUT_GRADE, detail.REP_CHOSE CHOSE, detail.REP_CONDITION_CMM CONDITION_CMM, detail.REP_FIN_AREA FIN_AREA, detail.REP_TOTAL_FEE_RATE TOTAL_FEE_RATE, null IS_RIGHT, null NOTSTAND_SEC_TYPE, null NOTSTAND_SEC_NUM, null REMAIN_TERM, null MAX_REMAIN_TERM, null MIN_REMAIN_TERM, null SHARES_TYPE, null INDUSTRY_SHARES, null INDUSTRY_SHARES2, null INVEST_STAGE, null SHARES_TYPE1, null SHARES_TYPE2, null SHARES_TYPE3, null IS_PLEDGE, null NOM_CAPI, NULL TARGET_TYPE3, asset.REP_ISSUE_PARTY_ID ISSUE_PARTY_ID, null TERM_MONTH, null GUARANTEE_CMT, null SPECIAL_CMT, null CONTRACT_NAME, null INCOME_RATIO, null DER_INSTR_RATIO, null DER_INSTR_INV_TYPE, null DER_INSTR_TARGET, null ACCT_MODE, null SPECIAL_CMT1, null MAX_YIELD, null MIN_YIELD, null BASIC_PRICE, null REG_DATE_PRICE, null TRADE_FEE, null PARTY_CODE, null CHECK_CODE, null MANAGER_ID, null TRUSTEE_ID, null TRU_ACT_TYPE, null INVEST_TYPE, null CAP_USE_INDU, null PLAN_SDATE, null PLAN_EDATE, null PRO_PROPERTY, null MAX_RATE, null MIN_RATE, null DEBT_SCALE, null BUY_STRUCT, null MANAGE_TYPE, null IS_CTRL_BOTTOM, null MGR_FEE_RATE, null TRU_FEE_RATE, null TRADE_FEE_RATE, null AGENCY_FEE_RATE, null OTHER_FEE_RATE, null ASSET_VALUE, null REGIST_ORG1, null MNG_ORG_NAME, null TRU_ORG_NAME, null FUND_INVEST_ASSET, null IN_ASSET_TYPE, NULL IN_ASSET_TYPE_CMM, detail.REP_REMARK REMARK, null IS_UNDER_ASSET, null IS_GOVERN_FUND, null GOVERN_INVEST_FUND, null FUND_ENPE_NAME, NULL TRUSTEE, 'E' STATUS, detail.CREATE_USER CREATE_USER, detail.CREATE_TIME CREATE_TIME, detail.UPDATE_USER UPDATE_USER, greatest(ifnull(ifnull(asset.UPDATE_TIME,asset.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')), ifnull(ifnull(info.UPDATE_TIME,info.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')), ifnull(ifnull(infotp.UPDATE_TIME,infotp.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')), ifnull(ifnull(customerinfo.UPDATE_TIME,customerinfo.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')), ifnull(ifnull(addq.UPDATE_TIME,addq.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')) ) UPDATE_TIME, detail.CREATE_DEPT DEPT_CODE, NULL ORG_CODE, 'bszg' data_source,/*数据来源*/ ifnull(OTHER.REP_PRIVATEFUND_FLAG,'02') PRIVATEFUND_FLAG, null privateprd_flag, ifnull(OTHER.REP_PRIVATEPRD_FLAG,'02') PRIVATE_FLAG, ifnull(OTHER.REP_bondtostock_flag,'02') bondtostock_flag, ifnull(OTHER.REP_PPPFLAG,'02') PPPFLAG, NOW() status_date, NULL CAP_USE_INDU_LEVEL2, NULL ISSUE_PARTY_NAME,/*发行机构*/ null SEC_CREDIT_GRADE_TYPE,/*债券信用评级*/ NULL SEC_MAIN_GRADE,/*主体评级*/ ifnull(info.BLN_AREA,(case info.ccy when 'CNY' then '01' when null then null else '02' end)) BLN_AREA,/*境内外*/ addq.INDUSTRY INDUSTRY_PBC,/*融资人所属行业一级分类（人行）*/ (case customerinfo.CUSTOMER_TYPE when '02' then 'C01' else ifnull(addq.CUSTOMER_OBJ_TYPE,'C03') end) CUSTOMER_OBJ_TYPE,/*客户主体类型*/ infotp.TYPE_8 ORG_ASSET_TYPE1,/*原资产一级分类*/ infotp.TYPE_6 ORG_ASSET_TYPE2,/*原资产二级分类*/ /*资产二级分类为信贷资产流转项目时根据是否小微企业信贷资产流转和收益权转让和受让形式判断*/ case when infotp.TYPE_6='P08' and OTHER.REP_SMALLCREDIT='02' then OTHER.REP_SMALLCREDIT when infotp.TYPE_6='P08' and OTHER.REP_SMALLCREDIT='01' and OTHER.REP_ASSIGNEE='001' then OTHER.REP_ASSIGNEE when infotp.TYPE_6='P08' and OTHER.REP_SMALLCREDIT='01' and OTHER.REP_ASSIGNEE='002' then OTHER.REP_ASSIGNEE else infotp.TYPE_7 end as ORG_ASSET_TYPE3,/*原资产三级分类*/
addq.city buy_place,/*发行人/融资人所属地区*/ ifnull(OTHER.REP_SMALLCREDIT,'02') ASSET_TYPE3,/*资产二级分类细分类*/ null PBC_ASSET_TYPE1,/*人行资产一级分类*/ null PBC_ASSET_TYPE2,/*人行产二级分类*/ null PBC_ASSET_TYPE3,/*人行产三级分类*/ null TRM_FUND_TYPE , /*交易所基金类型*/ null DEPO_TYPE, null RIVAL_PARTY_TYPE, case when ASSET.REP_ASSET_TYPE ='2201' then null when ASSET.REP_ASSET_TYPE ='2202' then null else detail.REP_PRIN_BASEAMT end as PRIN_BASEAMT, detail.REP_FMDATE FMDATE, case when ASSET.REP_ASSET_TYPE ='2201' then null when ASSET.REP_ASSET_TYPE ='2202' then null else case when T31.PAY_CYCLE='07' and T21.INT_TYPE='01' then '02' when T31.PAY_CYCLE='07' and T21.INT_TYPE='02' then '03' when T31.PAY_CYCLE!='07' and T21.INT_TYPE='01' then '04' when T31.PAY_CYCLE!='07' and T21.INT_TYPE='02' then '05' else null end end as COUPON_SPECIES, case when ASSET.REP_ASSET_TYPE ='2201' then null when ASSET.REP_ASSET_TYPE ='2202' then null else case when T31.PAY_CYCLE='08' then '02' else '01' END end as INTEREST_RULE_FLAG, case when ASSET.REP_ASSET_TYPE ='2201' then null when ASSET.REP_ASSET_TYPE ='2202' then null else DETAIL.REP_INTPAY_RULE end as INTPAY_RULE, case when ASSET.REP_ASSET_TYPE ='2201' then null when ASSET.REP_ASSET_TYPE ='2202' then null else case when T22.INT_TYPE='02' and T22.COEFFICIENT!=1 then '01' when T22.INT_TYPE='02' and T22.COEFFICIENT=1 then '02' when T22.INT_TYPE='01' then '02' else null end end as FLOAT_FACTOR_FLAG, detail.REP_STRUCT_GRADE STRUCT_GRADE, detail.REP_REPAYMENT_TYPE REPAYMENT_TYPE, case when ASSET.REP_ASSET_TYPE ='2201' then null when ASSET.REP_ASSET_TYPE ='2202' then null else case when T33.PAY_CYCLE='07' then '02' when T33.PAY_CYCLE='16' then '99' else '01' end end as PERIOD_REPAYMENT_FLAG, detail.REP_BASIC_ASSET_TYPE BASIC_ASSET_TYPE, detail.REP_EXCESS_PROFIT_RATE EXCESS_PROFIT_RATE, detail.REP_PLEDGE_TYPE PLEDGE_TYPE, detail.REP_PLEDGE_VALUE PLEDGE_VALUE, detail.REP_NATURE_GUARANTEE NATURE_GUARANTEE, detail.REP_RELATION_FINAN RELATION_FINAN, case when ASSET.REP_ASSET_TYPE ='2201' then null when ASSET.REP_ASSET_TYPE ='2202' then null else detail.REP_CONTAIN_TYPE end as CONTAIN_TYPE, detail.REP_EXERCISE_TYPE EXERCISE_TYPE, detail.REP_EXERCISE_DATE EXERCISE_DATE, detail.REP_FIRST_EXERCISE_DATE FIRST_EXERCISE_DATE, detail.REP_EXERCISE_PERIOD EXERCISE_PERIOD, detail.REP_EXERCISE_PRICE EXERCISE_PRICE, case when ASSET.REP_ASSET_TYPE ='2201' then null when ASSET.REP_ASSET_TYPE ='2202' then null else detail.REP_PERPETUAL_CLAUSE_TYPE end as PERPETUAL_CLAUSE_TYPE, case when ASSET.REP_ASSET_TYPE ='2201' then null when ASSET.REP_ASSET_TYPE ='2202' then null else detail.REP_DEFERRED_INTEREST_TYPE end as DEFERRED_INTEREST_TYPE, detail.REP_DEFERRED_INTEREST_INT DEFERRED_INTEREST_INT, detail.REP_FIRST_REPRCE_DATE FIRST_REPRCE_DATE, detail.REP_REPRCE_CYCLE REPRCE_CYCLE, detail.REP_PART_REDEM_FLAG PART_REDEM_FLAG, detail.REP_PART_REDEM_RATE PART_REDEM_RATE, case when ASSET.REP_ASSET_TYPE ='2201' then null when ASSET.REP_ASSET_TYPE ='2202' then null else a.INSITITUTE_CODE end as CREDIT_ORG_CODE, case when ASSET.REP_ASSET_TYPE ='2201' then null when ASSET.REP_ASSET_TYPE ='2202' then null else b.CUSTOMER_NAME end as CREDIT_ORG_NAME, null EQUITY_QUIT, null DEPT_EQUITY, null HOLD_PURPOSE, null FINANCIAL_COMISSUE, NULL BANK_SEC_CAPITAL, NULL BANK_SEC_PERPETUAL, NULL BANK_SEC_PREFER, NULL BANK_SEC_KZZQ, NULL BANK_SEC_ZXZQ, NULL ISUNLISTED, NULL IS_BZHPJ, info.ISSUER CHB_ISSUER_ID, info.MANAGER CHB_MANAGER_ID, info.FINANCIER CHB_FINANCIER_ID, case info.IS_SUS when 'Y' then '01' when 'N' then '02' else info.IS_SUS end PERPETUAL_FLAG, case info.IS_RIGHT when 'Y' then '01' when 'N' then '02' else info.IS_RIGHT end OPTION_FLAG, CASE WHEN infotp.TYPE_11 = '130' THEN '01' ELSE '02' END IS_BJSZQ, NULL IS_PERPETUAL, NULL IS_FBZB
FROM REP_ASSET_CREDIT_NONSTD DETAIL left JOIN REP_ASSET_DEPT ASSET on detail.REP_FINPROD_ID = ASSET.REP_FINPROD_ID left JOIN REP_ASSET_OTHER OTHER on detail.REP_FINPROD_ID = OTHER.REP_FINPROD_ID left join fin_product info on info.FINPROD_ID=detail.REP_FINPROD_ID left join FIN_PRODUCT_TYPE infotp on ifnull(info.P_FINPROD_ID,asset.REP_FINPROD_ID)=infotp.FINPROD_ID left join MST_CUSTOMER_INFO_ADD addq on info.FINANCIER=addq.CUSTOMER_ID left join mst_customer_info customerinfo on info.FINANCIER=customerinfo.CUSTOMER_ID
left join FIN_CASH_INFO T11 on T11.FINPROD_ID =detail.REP_FINPROD_ID AND T11.CASH_TYPE_2 = 'C02' LEFT JOIN FIN_RATE_INFO T21 ON (T21.CASH_ID = T11.CASH_ID AND T21.EFF_DATE = info.VDATE) LEFT JOIN FIN_CASH_PAY_RULE T31 ON (T31.CASH_ID = T11.CASH_ID AND T31.EFF_DATE = info.VDATE)
left join FIN_CASH_INFO T12 on T12.FINPROD_ID = detail.REP_FINPROD_ID and T12.CASH_TYPE_2 = 'C02' left join FIN_RATE_INFO T22 on T22.EFF_DATE = info.VDATE and T22.CASH_ID = T12.CASH_ID
left join FIN_CASH_INFO T13 on T13.FINPROD_ID = detail.REP_FINPROD_ID and T13.CASH_TYPE_2 = 'C01' LEFT JOIN FIN_PRODUCT T23 ON T23.FINPROD_ID = T13.FINPROD_ID LEFT JOIN FIN_CASH_PAY_RULE T33 ON (T33.CASH_ID = T13.CASH_ID AND T33.EFF_DATE = T23.VDATE)
left join (select t1.* from ( select row_number() over(partition by t.finprod_id order by t.update_time) idx,t.* from fin_product_credit t)t1 where t1.idx=1) tt on tt.FINPROD_ID = detail.REP_FINPROD_ID left join mst_customer_info_add a on tt.credit_flag = a.customer_id left join mst_customer_info b on b.customer_id = a.customer_id
WHERE 1 =1 and ifnull(info.IS_CHL,'N') = 'N' and ASSET.IS_REP_TARGET = 'Y' /*根据创建时间、更新时间和接口接入时间接入数据*/ AND( ifnull(asset.UPDATE_TIME,asset.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ifnull(info.UPDATE_TIME,info.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ifnull(infotp.UPDATE_TIME,infotp.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ifnull(customerinfo.UPDATE_TIME,customerinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ifnull(addq.UPDATE_TIME,addq.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*非标资产(票据或信用)报送信息*/ UNION ALL SELECT null ASSET_UUID, asset.FINPROD_MARKET_ID asset_code, null ASSET_TYPE, asset.REP_ASSET_TYPE ASSET_TYPE2, asset.REP_CCY CCY, asset.REP_TRADE_MARKET TRADE_MARKET, detail.REP_VDATE VDATE, detail.REP_MDATE MDATE, null DISCOUNT_YIELD,/*贴现利率*/ detail.REP_DISC_RATE ASSET_YIELD, null BASIS, detail.REP_AMT_SUM AMT, null BANK_NAME, null IS_STRUCT, null TARGET_TYPE, null TARGET, null ASSET_ID, asset.REP_FINPROD_NAME ASSET_NAME, null CHB_SECTYPE, null ISSUE_MODE, null PARTY_GRADE, null INSTIT_SIZE, null PARTY_TYPE1, null PARTY_TYPE3, null PARTY_TYPE2, null INDUSTRY, null INDUSTRY_LEVEL2, null REGIST_ORG, null REGISTORG_COMMENT, null RIVAL_PARTY, null TARGET_TYPE1, null TARGET_AMT, null COUNTRY_AREA, null PROFIT_TYPE, detail.REP_IS_RESALE IS_RESALE, null TERM_DATE, null RATE_FLAG, null INTPAY_CYCLE, null REPAY_CMT, null BASIS_TYPE, null FLOAT_FACTOR, null SPREAD_RATE, null FINANCIE, null FIN_ORG_CODE, null FCR_GRADE_IN, null FCR_GRADE_OUT, null FINANCIER_TYPE1, null FINANCIER_TYPE2, null FINANCIER_TYPE3, null FINANCE_PROJ, null INDUSTRY1, null INDUSTRY_LEVEL2_TYPE, null PRO_INDUSTRY, null PRO_INDUSTRY_LEVEL2, null INDUSTRY_FLAG, null MONIT_TYPE, null MON_TYPE_COMM, null GUA_TYPE, null GUA_TYPE_REMARK, null FINANCIER_GRADE, null IN_GRADE, null OUT_GRADE, null CHOSE, null CONDITION_CMM, null FIN_AREA, null TOTAL_FEE_RATE, detail.REP_IS_RIGHT IS_RIGHT, detail.REP_AST_BILL_TYPE NOTSTAND_SEC_TYPE, detail.REP_NUM NOTSTAND_SEC_NUM, detail.REP_REMAIN_TERM REMAIN_TERM, detail.REP_MAX_REMAIN_TERM MAX_REMAIN_TERM, detail.REP_MIN_REMAIN_TERM MIN_REMAIN_TERM, null SHARES_TYPE, detail.REP_INDUSTRY INDUSTRY_SHARES, detail.REP_INDUSTRY_LEVEL2 INDUSTRY_SHARES2, null INVEST_STAGE, null SHARES_TYPE1, null SHARES_TYPE2, null SHARES_TYPE3, null IS_PLEDGE, null NOM_CAPI, NULL TARGET_TYPE3, asset.REP_ISSUE_PARTY_ID ISSUE_PARTY_ID, null TERM_MONTH, null GUARANTEE_CMT, null SPECIAL_CMT, null CONTRACT_NAME, null INCOME_RATIO, null DER_INSTR_RATIO, null DER_INSTR_INV_TYPE, null DER_INSTR_TARGET, null ACCT_MODE, null SPECIAL_CMT1, null MAX_YIELD, null MIN_YIELD, null BASIC_PRICE, null REG_DATE_PRICE, null TRADE_FEE, null PARTY_CODE, null CHECK_CODE, null MANAGER_ID, null TRUSTEE_ID, null TRU_ACT_TYPE, null INVEST_TYPE, null CAP_USE_INDU, null PLAN_SDATE, null PLAN_EDATE, null PRO_PROPERTY, null MAX_RATE, null MIN_RATE, null DEBT_SCALE, null BUY_STRUCT, null MANAGE_TYPE, null IS_CTRL_BOTTOM, null MGR_FEE_RATE, null TRU_FEE_RATE, null TRADE_FEE_RATE, null AGENCY_FEE_RATE, null OTHER_FEE_RATE, null ASSET_VALUE, null REGIST_ORG1, null MNG_ORG_NAME, null TRU_ORG_NAME, null FUND_INVEST_ASSET, null IN_ASSET_TYPE, NULL IN_ASSET_TYPE_CMM, detail.REP_REMARK REMARK, null IS_UNDER_ASSET, null IS_GOVERN_FUND, null GOVERN_INVEST_FUND, null FUND_ENPE_NAME, NULL TRUSTEE, 'E' STATUS, detail.CREATE_USER CREATE_USER, detail.CREATE_TIME CREATE_TIME, detail.UPDATE_USER UPDATE_USER, greatest(ifnull(ifnull(asset.UPDATE_TIME,asset.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')), ifnull(ifnull(info.UPDATE_TIME,info.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')), ifnull(ifnull(infotp.UPDATE_TIME,infotp.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')), ifnull(ifnull(customerinfo.UPDATE_TIME,customerinfo.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')), ifnull(ifnull(addq.UPDATE_TIME,addq.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')) ) UPDATE_TIME, detail.CREATE_DEPT DEPT_CODE, NULL ORG_CODE, 'bszg' data_source,/*数据来源*/ ifnull