t_ws('','利率互换', FTP.FINPROD_ID) else concat_ws('','债券借贷', FTP.FINPROD_ID) end) ASSET_NAME, /*资产名称*/ NULL CHB_SECTYPE, /*具体类别*/ NULL ISSUE_MODE, /*发行方式*/ NULL PARTY_GRADE, /*发行机构主体信用评级*/ null INSTIT_SIZE, NULL PARTY_TYPE1, /*发行机构类型（按规模划分）*/ NULL PARTY_TYPE3, /*发行机构类型（按技术领域划分）*/ NULL PARTY_TYPE2, /*发行机构类型（按经济类型划分）*/ NULL INDUSTRY, /*发行机构所属行业一级分类*/ NULL INDUSTRY_LEVEL2, /*发行机构所属行业二级分类*/ NULL REGIST_ORG, /*登记托管机构*/ NULL REGISTORG_COMMENT, /* 登记托管机构说明*/ NULL RIVAL_PARTY, /*对手方*/ NULL TARGET_TYPE1, /*回购标的类别*/ NULL TARGET_AMT, /*回购标的金额*/ NULL COUNTRY_AREA, /*所属国家或地区*/ NULL PROFIT_TYPE, /*收/受益权类型*/ NULL IS_RESALE, /*是否属于买入返售*/ NULL TERM_DATE, /*期限（天）*/ NULL RATE_FLAG, /*是否有预期收益率*/ NULL INTPAY_CYCLE, /*付息频率（个月/次）*/ NULL REPAY_CMT, /*还本付息说明*/ NULL BASIS_TYPE, /*基准利率种类*/ NULL FLOAT_FACTOR, /*浮动因子*/ NULL SPREAD_RATE, /*利差*/ NULL FINANCIE, /*融资人*/ NULL FIN_ORG_CODE, /*融资人组织机构代码*/ NULL FCR_GRADE_IN, /*融资人内部信用评级*/ NULL FCR_GRADE_OUT, /*外部评级机构名称及融资人评级结果*/ NULL FINANCIER_TYPE1, /*融资人类型（按规模划分）*/ NULL FINANCIER_TYPE2, /*融资人类型（按技术领域划分）*/ NULL FINANCIER_TYPE3, /*融资人类型（按经济类型划分）*/ NULL FINANCE_PROJ, /*融资项目*/ NULL INDUSTRY1, /*融资人所属行业一级分类*/ NULL INDUSTRY_LEVEL2_TYPE, /*融资人所属行业二级分类*/ NULL PRO_INDUSTRY, /*融资项目所属行业一级分类*/ NULL PRO_INDUSTRY_LEVEL2, /*融资项目所属行业二级分类*/ NULL INDUSTRY_FLAG, /*项目是否属于重点监控行业和领域*/ NULL MONIT_TYPE, /*重点监控行业和领域类别*/ NULL MON_TYPE_COMM, /*重点监控行业和领域类别说明*/ NULL GUA_TYPE, /*担保方式*/ NULL GUA_TYPE_REMARK, /*担保方式说明*/ NULL FINANCIER_GRADE, /*融资人主体评级*/ NULL IN_GRADE, /*资产内部评级*/ NULL OUT_GRADE, /*资产外部评级*/ NULL CHOSE, /*选择权*/ NULL CONDITION_CMM, /*行权条件说明*/ NULL FIN_AREA, /*融资人所属地区*/ NULL TOTAL_FEE_RATE, /*融资总费率*/ NULL IS_RIGHT, /*是否为收/受益权*/ NULL NOTSTAND_SEC_TYPE, /*非标准化债券类资产类型*/ NULL NOTSTAND_SEC_NUM, /*非标准化债券类资产数量*/ NULL REMAIN_TERM, /*加权剩余期限(天)*/ NULL MAX_REMAIN_TERM, /*最长剩余期限(天)*/ NULL MIN_REMAIN_TERM, /*最短剩余期限(天)*/ NULL SHARES_TYPE, /*股票类型*/ NULL INDUSTRY_SHARES, /*行业一级分类*/ NULL INDUSTRY_SHARES2, /*行业二级分类*/ NULL INVEST_STAGE, /*投资阶段*/ NULL SHARES_TYPE1, /*投资企业类型（按规模划分）*/ NULL SHAR