LD, null MIN_YIELD, null BASIC_PRICE, null REG_DATE_PRICE, null TRADE_FEE, null PARTY_CODE, null CHECK_CODE, null MANAGER_ID, null TRUSTEE_ID, null TRU_ACT_TYPE, null INVEST_TYPE, null CAP_USE_INDU, null PLAN_SDATE, null PLAN_EDATE, null PRO_PROPERTY, null MAX_RATE, null MIN_RATE, null DEBT_SCALE, null BUY_STRUCT, null MANAGE_TYPE, null IS_CTRL_BOTTOM, null MGR_FEE_RATE, null TRU_FEE_RATE, null TRADE_FEE_RATE, null AGENCY_FEE_RATE, null OTHER_FEE_RATE, null ASSET_VALUE, null REGIST_ORG1, null MNG_ORG_NAME, null TRU_ORG_NAME, null FUND_INVEST_ASSET, null IN_ASSET_TYPE, null IN_ASSET_TYPE_CMM, detail.REP_REMARK REMARK, null IS_UNDER_ASSET, null IS_GOVERN_FUND, null GOVERN_INVEST_FUND, null FUND_ENPE_NAME, NULL TRUSTEE, 'E' STATUS, detail.CREATE_USER CREATE_USER, detail.CREATE_TIME CREATE_TIME, detail.UPDATE_USER UPDATE_USER, greatest(ifnull(ifnull(asset.UPDATE_TIME,asset.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')), ifnull(ifnull(info.UPDATE_TIME,info.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')), ifnull(ifnull(infotp.UPDATE_TIME,infotp.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')), ifnull(ifnull(customerinfo.UPDATE_TIME,customerinfo.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')), ifnull(ifnull(addq.UPDATE_TIME,addq.CREATE_TIME),STR_TO_DATE('1900-01-01','%Y-%m-%d')) ) UPDATE_TIME, detail.CREATE_DEPT DEPT_CODE, NULL ORG_CODE, 'bszg' data_source,/*数据来源*/ null PRIVATEFUND_FLAG, null privateprd_flag, null PRIVATE_FLAG, null bondtostock_flag, NULL PPPFLAG, NOW() status_date, NULL CAP_USE_INDU_LEVEL2, NULL ISSUE_PARTY_NAME,/*发行机构*/ null SEC_CREDIT_GRADE_TYPE,/*债券信用评级*/ NULL SEC_MAIN_GRADE,/*主体评级*/ ifnull(info.BLN_AREA,(case info.ccy when 'CNY' then '01' when null then null else '02' end)) BLN_AREA,/*境内外*/ addq.INDUSTRY INDUSTRY_PBC,/*融资人所属行业一级分类（人行）*/ (case customerinfo.CUSTOMER_TYPE when '02' then 'C01' else ifnull(addq.CUSTOMER_OBJ_TYPE,'C03') end) CUSTOMER_OBJ_TYPE,/*客户主体类型*/ infotp.TYPE_8 ORG_ASSET_TYPE1,/*原资产一级分类*/ infotp.TYPE_9 ORG_ASSET_TYPE2,/*原资产二级分类*/ infotp.TYPE_10 ORG_ASSET_TYPE3,/*原资产三级分类*/ infotp.TYPE_11 ORG_ASSET_TYPE4,/*原资产四级分类*/ infotp.TYPE_12 ORG_ASSET_TYPE5,/*原资产五级分类*/ infotp.TYPE_6 ORG_ASSET_TYPE_EX, addq.IS_FIN_LICENCE IS_FIN_LICENCE, addq.city buy_place,/*发行人/融资人所属地区*/ null ASSET_TYPE3,/*资产二级分类细分类*/ null PBC_ASSET_TYPE1,/*人行资产一级分类*/ null PBC_ASSET_TYPE2,/*人行产二级分类*/ null PBC_ASSET_TYPE3,/*人行产三级分类*/ null TRM_FUND_TYPE /*交易所基金类型*/ FROM REP_ASSET_BANK_DEPOSIT DETAIL left JOIN REP_ASSET_DEPT ASSET on detail.REP_FINPROD_ID = ASSET.REP_FINPROD_ID left join fin_product info on info.FINPROD_ID=detail.REP_FINPROD_ID left join FIN_PRODUCT_TYPE infotp on ifnull(info.P_FINPROD_ID,asset.REP_FINPROD_ID)=infotp.FINPROD_ID left join MST_CUSTOMER_INFO_ADD addq on info.FINANCIER=addq.CUSTOMER_ID left join mst_customer_info customerinfo on info.FINANCIER=customerinfo.CUSTOMER_ID left join REP_ASSET_OTHER ASSETOTHER on ASSETOTHER.REP_FINPROD_ID=info.FINPROD_ID WHERE 1 =1 and ifnull(info.IS_CHL,'N') = 'N' and ASSET.IS_REP_TARGET = 'Y' /*根据创建时间、更新时间和接口接入时间接入数据*/ AND( ifnull(asset.UPDATE_TIME,asset.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ifnull(info.UPDATE_TIME,info.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ifnull(infotp.UPDATE_TIME,infotp.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ifnull(customerinfo.UPDATE_TIME,customerinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ifnull(addq.UPDATE_TIME,addq.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*债券资产报送信息*/ UNION ALL SELECT null ASSET_UUID, asset.FINPROD_MARKET_ID asset_code, null ASSET_TYPE, asset.REP_ASSET_TYPE ASSET_TYPE2, asset.REP_CCY CCY, asset.REP_TRADE_MARKET TRADE_MARKET, null VDATE, null MDATE, null DISCOUNT_YIELD, null ASSET_YIELD, null BASIS, null AMT, null BANK_NAME, null IS_STRUCT, null TARGET_TYPE, null TARGET, detail.SEC_ID ASSET_ID, asset.REP_FINPROD_NAME ASSET_NAME, detail.REP_SECTYPE CHB_SECTYPE, detail.REP_ISSUE_MODE ISSUE_MODE, null PARTY_GRADE, case when addq.party_type1='01' then '01' when addq.party_type1='02' then '03' when addq.party_type1='03' then '04' when addq.party_type1='04' then '02' when addq.party_type1='05' then '99' end as instit_size, detail.REP_PARTY_TYPE1 PARTY_TYPE1, detail.REP_PARTY_TYPE3 PARTY_TYPE3, detail.REP_PARTY_TYPE2 PARTY_TYPE2, detail.REP_INDUSTRY INDUSTRY, detail.REP_INDUSTRY_LEVEL2 INDUSTRY_LEVEL2, detail.REP_REGIST_ORG REGIST_ORG, detail.REP_REGISTORG_COMMENT REGISTORG_COMMENT, null RIVAL_PARTY, null TARGET_TYPE1, null TARGET_AMT, null COUNTRY_AREA, null PROFIT_TYPE, null IS_RESALE, null TERM_DATE, null RATE_FLAG, null INTPAY_CYCLE, null REPAY_CMT, null BASIS_TYPE, null FLOAT_FACTOR, null SPREAD_RATE, info.ISSUER FINANCIE,/*取FIN_PRODUCT发行人*/ null FIN_ORG_CODE, null FCR_GRADE_IN, null FCR_GRADE_OUT, null FINANCIER_TYPE1, null FINANCIER_TYPE2, null FINANCIER_TYPE3, null FINANCE_PROJ, null INDUSTRY1, null INDUSTRY_LEVEL2_TYPE, null PRO_INDUSTRY, null PRO_INDUSTRY_LEVEL2, null INDUSTRY_FLAG, null MONIT_TYPE, null MON_TYPE_COMM, null GUA_TYPE, null GUA_TYPE_REMARK, null FINANCIER_GRADE, null IN_GRADE, null OUT_GRADE, null CHOSE, null CONDITION_CMM, null FIN_AREA, null TOTAL_FEE_RATE, null IS_RIGHT, null NOTSTAND_SEC_TYPE, null NOTSTAND_SEC_NUM, null REMAIN_TERM, null MAX_REMAIN_TERM, null MIN_REMAIN_TERM, null SHARES_TYPE, null INDUSTRY_SHARES, null INDUSTRY_SHARES2, null INVEST_STAGE, null SHARES_TYPE1, null SHARES_TYPE2, null SHARES_TYPE3, null IS_PLEDGE, null NOM_CAPI, NULL TARGET_TYPE3, asset.REP_ISSUE_PARTY_ID ISSUE_PARTY_ID, null TERM_MONTH, null GUARANTEE_CMT, null SPECIAL_CMT, null CONTRACT_NAME, null INCOME_RATIO, null DER_INSTR_RATIO, null DER_INSTR_INV_TYPE, null DER_INSTR_TARGET, null ACCT_MODE, null SPECIAL_CMT1, null MAX_YIELD, null MIN_YIELD, null BASIC_PRICE, null REG_DATE_PRICE, null TRADE_FEE, null PARTY_CODE, null CHECK_CODE, null MANAGER_ID, null TRUSTEE_ID, null TRU_ACT_TYPE, null INVEST_TYPE, null CAP_USE_INDU, null PLAN_SDATE, null PLAN_EDATE, null PRO_PROPERTY, null MAX_RATE, null MIN_RATE, null DEBT_SCALE, null BUY_STRU