1,/*人行资产一级分类*/ null PBC_ASSET_TYPE2,/*人行产二级分类*/ null PBC_ASSET_TYPE3,/*人行产三级分类*/ null TRM_FUND_TYPE /*交易所基金类型*/ FROM REP_ASSET_BOND DETAIL left JOIN REP_ASSET_DEPT ASSET on detail.REP_FINPROD_ID = ASSET.REP_FINPROD_ID left join fin_product info on info.FINPROD_ID=detail.REP_FINPROD_ID left join FIN_PRODUCT_TYPE infotp on ifnull(info.P_FINPROD_ID,asset.REP_FINPROD_ID)=infotp.FINPROD_ID left join MST_CUSTOMER_INFO_ADD addq/*债券用发行人关联*/ on info.ISSUER=addq.CUSTOMER_ID left join mst_customer_info customerinfo on info.ISSUER=customerinfo.CUSTOMER_ID left join REP_ASSET_OTHER ASSETOTHER on ASSETOTHER.REP_FINPROD_ID=info.FINPROD_ID left join FIN_PRODUCT_ADD fpd on detail.SEC_ID = fpd.appear_market_id
