E, /*资产/负债类别*/ (case FTP.FINPROD_TYPE2 when 'F35' then '1404' when 'F11' then '1499' when 'F12' then '1401' when 'F13' then '1499' when 'F14' then '1402' else '1405' end) ASSET_TYPE2, FTP.CCY CCY, /*币种*/ (case FTP.FINPROD_TYPE2 when 'F35' then '18' when 'F11' then '18' when 'F12' then '17' when 'F13' then '17' when 'F14' then '17' else '01' end) TRADE_MARKET, NULL VDATE, /*起息日*/ NULL MDATE, /*到期日*/ NULL DISCOUNT_YIELD, /*贴现利率*/ NULL ASSET_YIELD, /*收益率/年利率*/ NULL BASIS, /* 计息基础*/ NULL AMT, /*金额*/ NULL BANK_NAME, /*资金存入银行*/ NULL IS_STRUCT, /*是否为结构性存款*/ NULL TARGET_TYPE, /*构性存款挂钩标的类别*/ NULL TARGET, /*结构性存款挂钩标的*/ NULL ASSET_ID, /*资产代码*/ (case FTP.FINPROD_TYPE2 when 'F35' then concat_ws('','期权', FTP.FINPROD_ID) when 'F11' then concat_ws('','外汇即期', FTP.FINPROD_ID) when 'F12' then concat_ws('','外汇远期', FTP.FINPROD_ID) when 'F13' then concat_ws('','外汇掉期', FTP.FINPROD_ID) when 'F14' then concat_ws('','利率互换', FTP.FINPROD_ID) else concat_ws('','债券借贷', FTP.FINPROD_ID) end) ASSET_NAME, /*资产名称*/ NULL CHB_SECTYPE, /*具体类别*/ NULL ISSUE_MODE, /*发行方式*/ NULL PARTY_GRADE, /*发行机构主体信用评级*/ null INSTIT_SIZE, NULL PARTY_TYPE1, /*发行机构类型（按规模划分）*/ NULL PARTY_TYPE3, /*发行机构类型（按技术领域划分）*/ NULL PARTY_TYPE2, /*发行机构类型（按经济类型划分）*/ NULL INDUSTRY, /*发行机构所属行业一级分类*/ NULL INDUSTRY_LEVEL2, /*发行机构所属行业二级分类*/ NULL REGIST_ORG, /*登记托管机构*/ NULL REGISTORG_COMMENT, /* 登记托管机构说明*/ NULL RIVAL_PARTY, /*对手方*/ NULL TARGET_TYPE1, /*回购标的类别*/ NULL TARGET_AMT, /*回购标的金额*/ NULL COUNTRY_AREA, /*所属国家或地区*/ NULL PROFIT_TYPE, /*收/受益权类型*/ NULL IS_RESALE, /*是否属于买入返售*/ NULL TERM_DATE, /*期限（天）*/ NULL RATE_FLAG, /*是否有预期收益率*/ NULL INTPAY_CYCLE, /*付息频率（个月/次）*/ NULL REPAY_CMT, /*还本付息说明*/ NULL BASIS_TYPE, /*基准利率种类*/ NULL FLOAT_FACTOR, /*浮动因子*/ NULL SPREAD_RATE, /*利差*/ NULL FINANCIE, /*融资人*/ NULL FIN_ORG_CODE, /*融资人组织机构代码*/ NULL FCR_GRADE_IN, /*融资人内部信用评级*/ NULL FCR_GRADE_OUT, /*外部评级机构名称及融资人评级结果*/ NULL FINANCIER_TYPE1, /*融资人类型（按规模划分）*/ NULL FINANCIER_TYPE2, /*融资人类型（按技术领域划分）*/ NULL FINANCIER_TYPE3, /*融资人类型（按经济类型划分）*/ NULL FINANCE_PROJ, /*融资项目*/ N