LL ASSET_TYPE3, /*资产二级分类细分类*/ NULL PBC_ASSET_TYPE1, /*人行资产一级分类*/ NULL PBC_ASSET_TYPE2, /*人行产二级分类*/ NULL PBC_ASSET_TYPE3,/*人行产三级分类*/ null TRM_FUND_TYPE /*交易所基金类型*/ FROM FIN_TRADE_PRODUCT FTP LEFT JOIN MST_COUNTER_PARTY MSP ON FTP.COUNTER_ID = MSP.COUNTER_ID LEFT JOIN FIN_PRODUCT_TYPE FPTYPE ON FTP.FINPROD_ID = FPTYPE.FINPROD_ID LEFT JOIN FIN_PRODUCT INFO ON INFO.FINPROD_ID=FTP.FINPROD_ID left join MST_CUSTOMER_INFO_ADD addq on info.FINANCIER=addq.CUSTOMER_ID left join REP_ASSET_OTHER ASSETOTHER on ASSETOTHER.REP_FINPROD_ID=info.FINPROD_ID WHERE FTP.FINPROD_TYPE2 IN ('F11', 'F12', 'F13', 'F14', 'F29', 'F30','F35') AND ifnull(INFO.IS_CHL,'N') = 'N' /*根据创建时间、更新时间和接口接入时间接入数据*/ AND( ifnull(FTP.UPDATE_TIME,FTP.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} OR ifnull(MSP.UPDATE_TIME,MSP.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ifnull(addq.UPDATE_TIME,addq.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} OR ifnull(FPTYPE.UPDATE_TIME,FPTYPE.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) UNION ALL /*拆借、质押式回购、买断式回购*/ SELECT null ASSET_UUID, fp.finprod_id asset_code, '02' ASSET_TYPE, (case fp.finprod_type2 when 'F02' then '1902' when 'F04' then '1902' when 'F03' then '1108' when 'F05' then '1108' when 'F08' then '1901' else '1107' end) ASSET_TYPE2, fp.CCY CCY, ifnull(fp.trade_market, '17') TRADE_MARKET, fp.vdate VDATE, fp.mdate MDATE, null DISCOUNT_YIELD, fp.int_rate * 100 ASSET_YIELD, (case fp.BASIS when 'A/365' then '03' else '02' end) BASIS null AMT, null BANK_NAME, null IS_STRUCT, null TARGET_TYPE, null TARGET, null ASSET_ID, null ASSET_NAME, null CHB_SECTYPE, null ISSUE_MODE, null PARTY_GRADE, null INSTIT_SIZE, null PARTY_TYPE1, null PARTY_TYPE3, null PARTY_TYPE2, null INDUSTRY, null INDUSTRY_LEVEL2, null REGIST_ORG, null REGISTORG_COMMENT, fp.counter_id RIVAL_PARTY, case when fp.finprod_type2 in ('F02', 'F03', 'F04', 'F05') then '01' else null end as TARGET_TYPE1, case when fp.finprod_type2 in ('F02', 'F03', 'F04', 'F05') then (select ifnull(sum(dp.pledge_number) * 100, fp.prin) from FIN_DEAL_PLEDGE dp where dp.finprod_id = fp.finprod_id) else null end as TARGET_AMT, null COUNTRY_AREA, null PROFIT_TYPE, null IS_RESALE, null TERM_DATE, null RATE_FLAG, null INTPAY_CYCLE, null REPAY_CMT, null BASIS_TYPE, null FLOAT_FACTOR, null SPREAD_RATE, null FINANCIE, null FIN_ORG_CODE, null FCR_GRADE_IN, null FCR_GRADE_OUT, null FINANCIER_TYPE1, null FINANCIER_TYPE2, null FINANCIER_TYPE3, null FINANCE_PROJ, null INDUSTRY1, null INDUSTRY_LEVEL2_TYPE, null PRO_INDUSTRY, null PRO_INDUSTRY_LEVEL2, null INDUSTRY_FLAG, null MONIT_TYPE, null MON_TYPE_COMM, null GUA_TYPE, null GUA_TYPE_REMARK, null FINANCIER_GRADE, null IN_GRADE, null OUT_GRADE, null CHOSE, null CONDITION_CMM, null FIN_AREA, null TOTAL_FEE_RATE, null IS_RIGHT, null NOTSTAND_SEC_TYPE, null NOTSTAND_SEC_NUM, null REMAIN_TERM, null MAX_REMAIN_TERM, null MIN_REMAIN_TERM, null SHARES_TYPE, null INDUSTRY_SHARES, null INDUSTRY_SHARES2, null INVEST_STAGE, null SHARES_TYPE1, null SHARES_TYPE2, null SHARES_TYPE3, null IS_PLEDGE, null NOM_CAPI, NULL TARGET_TYPE3, null ISSUE_PARTY_ID, null TERM_MONTH, null GUARANTEE_CMT, null SPECIAL_CMT, null CONTRACT_NAME, null INCOME_RATIO, null DER_INSTR_RATIO, null DER_INSTR_INV_TYPE, null DER_INSTR_TARGET, null ACCT_MODE, null SPECIAL_CMT1, null MAX_YIELD, null MIN_YIELD, null BASIC_PRICE, null REG_DATE_PRICE, null TRADE_FEE, null PARTY_CODE, null CHECK_CODE, null MANAGER_ID, null TRUSTEE_ID, null TRU_ACT_TYPE, null INVEST_TYPE, null CAP_USE_INDU, null PLAN_SDATE, null PLAN_EDATE, null PRO_PROPERTY, null MAX_RATE, null MIN_RATE, null DEBT_SCALE, null BUY_STRUCT, null MANAGE_TYPE, null IS_CTRL_BOTTOM, null MGR_FEE_RATE, null TRU_FEE_RATE, null TRADE_FEE_RATE, null AGENCY_FEE_RATE, null OTHER_FEE_RATE, null ASSET_VALUE, null REGIST_ORG1, null MNG_ORG_NAME, null TRU_ORG_NAME, null FUND_INVEST_ASSET, null IN_ASSET_TYPE, null IN_ASSET_TYPE_CMM, null REMARK, null IS_UNDER_ASSET, null IS_GOVERN_FUND, null GOVERN_INVEST_FUND, null FUND_ENPE_NAME, NULL TRUSTEE, (case ifnull(td.TRADE_id, 'null') when 'null' then 'E' else 'D' end) STATUS, fp.CREATE_USER CREATE_USER, fp.CREATE_TIME CREATE_TIME, fp.UPDATE_USER UPDATE_USER, greatest(ifnull(ifnull(fp.UPDATE_TIME, fp.CREATE_TIME), STR_TO_DATE('1900-01-01', '%Y-%m-%d')), ifnull(ifnull(info.UPDATE_TIME, info.CREATE_TIME), STR_TO_DATE('1900-01-01', '%Y-%m-%d')), ifnull(ifnull(infotp.UPDATE_TIME, infotp.CREATE_TIME), STR_TO_DATE('1900-01-01', '%Y-%m-%d')), ifnull(ifnull(customerinfo.UPDATE_TIME, customerinfo.CREATE_TIME), STR_TO_DATE('1900-01-01', '%Y-%m-%d')), ifnull(ifnull(addq.UPDATE_TIME, addq.CREATE_TIME), STR_TO_DATE('1900-01-01', '%Y-%m-%d')), ifnull(ifnull(td.UPDATE_TIME, td.CREATE_TIME), STR_TO_DATE('1900-01-01', '%Y-%m-%d')), ifnull(ifnull(counterparty.UPDATE_TIME,counterparty.CREATE_TIME), STR_TO_DATE('1900-01-01','%Y-%m-%d'))) UPDATE_TIME, null DEPT_CODE, NULL ORG_CODE, 'bszg' data_source, /*数据来源*/ null PRIVATEFUND_FLAG, null privateprd_flag, null PRIVATE_FLAG, null bondtostock_flag, NULL PPPFLAG, NOW() status_date, NULL CAP_USE_INDU_LEVEL2, NULL ISSUE_PARTY_NAME, /*发行机构*/ null SEC_CREDIT_GRADE_TYPE, NULL SEC_MAIN_GRADE, /**/ '01' BLN_AREA, /*境内外*/ addq.INDUSTRY INDUSTRY_PBC, /*融资人所属行业一级分类（人行）*/ (case customerinfo.CUSTOMER_TYPE when '02' then 'C01' else ifnull(addq.CUSTOMER_OBJ_TYPE,'C03') end) CUSTOMER_OBJ_TYPE,/*客户主体类型*/ infotp.TYPE_8 ORG_ASSET_TYPE1,/*原资产一级分类*/ infotp.TYPE_9 ORG_ASSET_TYPE2,/*原资产二级分类*/ infotp.TYPE_10 ORG_ASSET_TYPE3,/*原资产三级分类*/ infotp.TYPE_11 ORG_ASSET_TYPE4,/*原资产四级分类*/ infotp.TYPE_12 ORG_ASSET_TYPE5,/*原资产五级分类*/ infotp.TYPE_6 ORG_ASSET_TYPE_EX, addq.IS_FIN_LICENCE IS_FIN_LICENCE, addq.city buy_place, /*发行人/融资人所属地区*/ null ASSET_TYPE3, /*资产二级分类细分类*/ null PBC_ASSET_TYPE1, /*人行资产一级分类*/ null PBC_ASSET_TYPE2, /*人行产二级分类*/ null PBC_ASSET_TYPE3,/*人行产三级分类*/ null TRM_FUND_TYPE /*交易所基金类型*/ FROM fin_trade_product fp left join fin_product info on info.FINPROD_ID = fp.FINPROD_ID left join FIN_PRODUCT_TYPE infotp on fp.FINPROD_ID = infotp.FINPROD_ID left join MST_CUSTOMER_INFO_ADD addq on info.FINANCIER = addq.CUSTOMER_ID left join mst_customer_info customerinfo on info.FINANCIER = customerinfo.CUSTOMER_ID left join trd_product_deal td on Fp.FINPROD_ID = tD.P_TRADE_ID left join REP_ASSET_OTHER ASSETOTHER on ASSETOTHER.REP_FINPROD_ID=info.FINPROD_ID left join mst_counter_party counterparty on counterparty.COUNTER_ID = fp.COUNTER_ID WHERE 1 = 1 and fp.branch = 0 and fp.finprod_type2 in ('F02', 'F03', 'F04', 'F05') and (fp.data_source is null or fp.data_source!='01') /*根据创建时间、更新时间和接口接入时间接入数据*/ AND( ifnull(fp.UPDATE_TIME,fp.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ifnull(info.UPDATE_TIME,info.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ifnull(infotp.UPDATE_TIME,infotp.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ifnull(customerinfo.UPDATE_TIME,customerinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ifnull(td.UPDATE_TIME,td.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ifnull(addq.UPDATE_TIME,addq.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or ifnull(counterparty.UPDATE_TIME,counterparty.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*拆借、质押式回购、买断式回购*/

